        const double t_c = vdot(oc, d), dist2 = vdot(oc, oc) - t_c * t_c;   /* broad phase: the ray's line against the bounding sphere */
        if (dist2 > b->rad * b->rad || (t_c > 0 && vdot(oc, oc) > b->rad * b->rad)) continue;
